'use strict';
// «Мой профиль» и уведомления
/* ═════════════ Profiles ═════════════ */
function profileDlg(){
  const u=me();const st={};
  openModal({size:'mid',live:true,render:m=>{
    const ws=u.wallets||[];
    return {title:'Мой профиль',sub:esc(u.fio),body:`
    ${kbBox(kbStat(),{link:'pf-kb'})}
    <div class="box"><h3>Основное</h3><div class="kv"><div><span class="k">ФИО</span><span class="v">${esc(u.fio)}</span></div>${isAdmin()?'':`<div><span class="k">Отображаемое имя</span><span class="v">${esc(u.short||'')} <button class="linkbtn" id="pf-short">Изменить</button></span></div>`}<div><span class="k">Логин</span><span class="v mono">${esc(u.login)}</span></div><div><span class="k">Телефон</span><span class="v">${u.phone?esc(fmtPhone(u.phone)):'—'}</span></div><div><span class="k">Роль</span><span class="v">${isAdmin()?'Администратор платформы':esc(myRole().name)}</span></div></div></div>
    <div class="box"><h3>Telegram для уведомлений</h3>${u.tg?`<div class="row">${pill('Привязан',{Привязан:['green','check']})}<span class="mono">${esc(u.tg)}</span><div class="grow"></div><button class="btn sm" id="pf-tgchat" title="Макет: сообщения бота с кнопками для отчётов и задач">${ic('chat','sm')}Чат с ботом</button><button class="btn sm" id="pf-tgtest">${ic('tg','sm')}Проверить бота</button><button class="btn sm ghost" id="pf-untg">Отвязать</button></div><label class="check-row"><input type="checkbox" class="sw" id="pf-tgplain" ${u.tgPlain?'checked':''}><span class="grow">Сообщения простым текстом<div class="hint">Бот присылает таблицы и раскрывающиеся разделы. Включите, если в вашем Telegram они показываются неверно (старая версия приложения). Кнопки под сообщениями останутся.</div></span></label>`:`<div class="note warn">${ic('alert')}<span>Telegram не привязан: напоминания не приходят, а восстановить пароль самостоятельно нельзя.</span></div><div class="row" style="flex-wrap:wrap"><span class="mono" style="overflow-wrap:anywhere">t.me/buhuchet_bot?start=a7f3c91e</span><button class="btn sm" id="pf-tglink">${ic('copy','sm')}Скопировать ссылку</button>${u.tgPrev?`<button class="btn sm cta" id="pf-tgdemo">Демо: привязать тот же Telegram</button><button class="btn sm cta" id="pf-tgother">Демо: открыть ссылку в другом Telegram</button>${tgSecOf(u,u.tgPrev).length?`<button class="btn sm" id="pf-tgprev" title="Макет: сообщение бота в отвязанном чате и кнопка «Это не я»">${ic('chat','sm')}Демо: прежний чат</button>`:''}`:`<button class="btn sm cta" id="pf-tgdemo">Демо: привязать</button>`}</div><div class="hint">Ссылка одноразовая и действует 15 минут. Бот проверит её, привяжет чат и пришлёт подтверждение.${u.tgPrev?` Прежний Telegram ${esc(u.tgPrev)}: другой чат бот привяжет только по коду, который пришлёт туда.`:''}</div>`}</div>
    ${isAdmin()?'':`<div class="box"><h3>Мои реквизиты для переводов<span class="grow"></span><button class="btn sm" id="pf-addw">${ic('plus','sm')}Добавить</button></h3>${ws.length?`<div class="tbl-wrap"><table class="mini m-cards"><thead><tr><th>Вид</th><th>Банк или кошелёк</th><th>Номер</th><th>Получатель</th><th></th><th></th></tr></thead><tbody>${ws.map((w,i)=>`<tr><td>${w.kind==='phone'?ic('phone','sm'):ic('wallet','sm')} ${esc(rqKindL(w))}</td><td>${esc(rqProv(w))}</td><td class="mono">${esc(rqNum(w))}</td><td>${esc(w.name||'—')}</td><td>${w.main?pill('Основной',{Основной:['green','star']}):`<button class="linkbtn" data-main="${i}">Сделать основным</button>`}</td><td class="num" style="white-space:nowrap"><button class="icon-btn sm" data-edw="${i}" title="Изменить" aria-label="Изменить реквизит">${ic('edit','sm')}</button><button class="icon-btn sm" data-delw="${i}" title="Удалить" aria-label="Удалить реквизит">${ic('trash','sm')}</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="note">${ic('info')}<span>Реквизитов нет. Без них кнопка «Напомнить в WhatsApp» не сможет подставить, куда переводить деньги.</span></div>`}<div class="hint">Счёт или кошелёк — или перевод по номеру телефона, привязанному к нескольким банкам и кошелькам. Видны вам, владельцу и главному бухгалтеру. Провайдер выбирается из справочника платформы.</div></div>`}
    ${isAdmin()?'':notifyBox(u)}
    <div class="box"><h3>Личные настройки</h3><div class="form">${fld('Тема',sel('pf-theme',[['light','Светлая'],['dark','Тёмная']],effTheme()),{id:'pf-theme'})}</div>
      <div class="row" style="margin-top:10px"><span class="grow"><b>Знакомые элементы в показах</b><div class="hint">Показы «Базы знаний» пропускают то, что вам уже объяснили</div></span><button class="btn sm" id="pf-known">${ic('refresh','sm')}Показывать всё заново</button></div></div>
    <div class="box"><h3>Смена пароля</h3><div class="form">${fld('Текущий пароль',pwInp('pf-p0','','autocomplete="current-password"'),{id:'pf-p0'})}<div></div>${fld('Новый пароль',pwInp('pf-p1','','autocomplete="new-password"'),{id:'pf-p1',hint:'Не короче 8 символов'})}${fld('Повторите',pwInp('pf-p2','','autocomplete="new-password"'),{id:'pf-p2'})}</div><div class="row"><button class="btn sm" id="pf-pass">Сменить пароль</button></div></div>`,
    foot:`<div class="grow"></div><button class="btn cta" data-close>Готово</button>`,
    mount(el){
      const q=s=>el.querySelector(s);
      if(q('#pf-kb'))q('#pf-kb').onclick=()=>{m.close();go('kb','level')};
      if(q('#pf-short'))q('#pf-short').onclick=()=>shortDlg(u,()=>m.draw());
      bindNotify(el,u,m);q('#pf-known').onclick=()=>tKnownReset(()=>m.draw());
      q('#pf-theme').onchange=e=>setTheme(e.target.value,$('#theme'));
      if(q('#pf-untg'))q('#pf-untg').onclick=()=>{tgSecSend(u,'unlink');u.tgPrev=u.tg;u.tg=null;log('emp',u.id,'Telegram отвязан');m.draw();toast('Telegram отвязан')};
      // Поток Т (13.11.2026): «Проверить бота» — сообщение с таблицей и кнопкой; «Сообщения простым текстом» — запасной вид для старого приложения Telegram
      if(q('#pf-tgchat'))q('#pf-tgchat').onclick=tgStaffDlg;
      if(q('#pf-tgtest'))q('#pf-tgtest').onclick=()=>{tgSvc(u,'Проверка бота');tgBotDlg(u,[tgTestMsg()],{sub:'Бот прислал проверочное сообщение в '+u.tg})};
      if(q('#pf-tgplain'))q('#pf-tgplain').onchange=e=>{u.tgPlain=e.target.checked;log('emp',u.id,`Сообщения бота простым текстом: ${u.tgPlain?'включено':'выключено'}`);toast(u.tgPlain?'Бот будет присылать простой текст':'Бот будет присылать таблицы','tg')};
      if(q('#pf-tglink'))q('#pf-tglink').onclick=()=>copyText('https://t.me/buhuchet_bot?start=a7f3c91e','Ссылка скопирована',true);
      if(q('#pf-tgdemo'))q('#pf-tgdemo').onclick=()=>{u.tg=u.tgPrev||'@'+u.login;delete u.tgPrev;log('emp',u.id,'Telegram привязан');tgSvc(u,'Telegram привязан');m.draw();toast('Telegram привязан','tg')};
      if(q('#pf-tgother'))q('#pf-tgother').onclick=()=>tgRelinkDlg(u,()=>m.draw());
      // Поток Т, задача Т4 (13.11.2026): сообщение «Telegram отвязан» приходит в прежний чат с кнопкой «Это не я»; после смены пароля макет сразу показывает сообщение бота
      if(q('#pf-tgprev'))q('#pf-tgprev').onclick=()=>tgPrevDlg(u,()=>m.draw());
      if(q('#pf-addw'))q('#pf-addw').onclick=()=>walletDlg(u,()=>m.draw());
      $$('[data-edw]',el).forEach(b=>b.onclick=()=>walletDlg(u,()=>m.draw(),u.wallets[+b.dataset.edw]));
      $$('[data-delw]',el).forEach(b=>b.onclick=()=>{const w=u.wallets[+b.dataset.delw];confirmDlg({title:'Удалить реквизит?',text:`${esc(rqProv(w))} ${esc(rqNum(w))} больше не будет подставляться в напоминания.`,ok:'Удалить',danger:true,run:()=>{u.wallets.splice(+b.dataset.delw,1);if(u.wallets.length&&!u.wallets.some(x=>x.main))u.wallets[0].main=true;m.draw();toast('Реквизит удалён')}})});
      $$('[data-main]',el).forEach(b=>b.onclick=()=>{u.wallets.forEach((w,i)=>w.main=i===+b.dataset.main);m.draw()});
      // Новый пароль не совпадает с текущим (решение заказчика 27.10.2026); сменённый пароль в макете действует до перезагрузки страницы
      q('#pf-pass').onclick=()=>{const u=me(),cur=lgPass(u);const a=setErr(el,'pf-p0',val(el,'pf-p0')===cur?'':'Текущий пароль неверный'+(cur==='demo'?' (демо: demo)':''));const p=val(el,'pf-p1');const b=setErr(el,'pf-p1',p.length<8?'Не короче 8 символов':p===cur?LG_T.same:'');const c=setErr(el,'pf-p2',p===val(el,'pf-p2')?'':'Пароли не совпадают');if(a&&b&&c){LG_PW[u.login]=p;if(!u.pwLocked)u.pwBad=0;if(u.id==='admin')admReset();tgSecSend(u,'pass');toast('Пароль изменён. Другие сеансы завершены.','key');['pf-p0','pf-p1','pf-p2'].forEach(i=>el.querySelector('#'+i).value='');tgPassDlg(u)}};
    }};
  }});
}
// Отображаемое имя меняет сам сотрудник (решение заказчика 06.11.2026); смена пишется в историю сотрудника
function shortDlg(u,done){openModal({form:true,render:()=>({title:'Отображаемое имя',sub:esc(u.fio),body:`<div class="form">${fld('Отображаемое имя',inp('sh-v',u.short||'','maxlength="40"'),{req:true,full:true,id:'sh-v',hint:shortHint})}</div>`,
  foot:'<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="sh-ok">Сохранить</button>',mount(el,m){bindShort(el,'sh-v',()=>u.fio,shortManual(u));$('#sh-ok',el).onclick=()=>{const sh=readShort(el,'sh-v',u.fio);if(!setErr(el,'sh-v',shortErr(sh,u.id)))return;
    if(sh!==u.short){log('emp',u.id,`Отображаемое имя: «${u.short}» → «${sh}»`);u.short=sh;touch(u)}m.close();refreshAll();renderSide();if(done)done();toast('Отображаемое имя сохранено','user')}}})})}
/* Уведомления: владелец и главбух выбирают режим; сотрудник получает своё */
const NMODES=[['all','Все','Сроки и просрочки отчётов всех сотрудников, задачи, сводка за неделю'],['digest','Только просрочки и сводка','Без ежедневных напоминаний о сроках: только просрочки, ручные задачи и сводка за неделю'],['manual','Только ручные задачи','Новые задачи, поставленные вручную, их комментарии и выполнение. Регулярные задачи по отчётам не приходят']];
const NKINDS=[['before','Напоминания за N дней до срока по отчётам других сотрудников'],['over','Просрочки по отчётам других сотрудников'],['tasks','Ручные задачи: новые, комментарии, выполнение'],['regtasks','Регулярные задачи по отчётам'],['week','Сводка за неделю — в день, выбранный организацией (по умолчанию понедельник)']];
function notifyOf(u){u.notify=u.notify||{mode:'all',off:{}};return u.notify}
function notifyBox(u){const n=notifyOf(u);const boss=u.role==='owner'||u.role==='chief';
  const on=k=>!n.off[k]&&(n.mode==='all'||(n.mode==='digest'&&['over','tasks','week'].includes(k))||(n.mode==='manual'&&k==='tasks'));
  return `<div class="box"><h3>Уведомления в Telegram</h3>${boss?`<div class="fl-list" style="max-height:none" role="radiogroup" aria-label="Какие уведомления получать">${NMODES.map(([k,l,h])=>`<label><input type="radio" name="pf-nm" value="${k}" ${n.mode===k?'checked':''}> <span><b>${l}</b><div class="hint">${h}</div></span></label>`).join('')}</div>`:`<div class="note">${ic('info')}<span>Вы получаете напоминания по своим отчётам и задачам. Владелец и главный бухгалтер получают ещё и по всей организации, если не выбрали другой режим.</span></div>`}
  <label class="check-row"><input type="checkbox" class="sw" checked disabled aria-label="Напоминания по моим отчётам"><span class="grow">По моим отчётам: за N дней, в день срока и при просрочке — приходят всегда, отключить нельзя</span></label>
  ${NKINDS.filter(([k])=>boss||!['week','before','over'].includes(k)).map(([k,l])=>`<label class="check-row"><input type="checkbox" class="sw" data-nk="${k}" ${on(k)?'checked':''} ${boss&&n.mode!=='all'&&!on(k)&&!n.off[k]?'disabled':''}><span class="grow">${l}</span></label>`).join('')}
  <span class="hint">${boss?'Режим и переключатели меняют только уведомления по отчётам других сотрудников и по задачам. Отключённый переключатель — это то, что не входит в выбранный режим.':'Напоминания по вашим отчётам нельзя отключить: их получаете вы, главный бухгалтер и владелец.'}</span></div>`}
function bindNotify(el,u,m){const n=notifyOf(u);
  $$('[name="pf-nm"]',el).forEach(r=>r.onchange=()=>{n.mode=r.value;n.off={};log('emp',u.id,'Уведомления: '+NMODES.find(x=>x[0]===r.value)[1]);m.draw();toast('Режим уведомлений сохранён','bell')});
  $$('[data-nk]',el).forEach(x=>x.onchange=()=>{if(x.checked)delete n.off[x.dataset.nk];else n.off[x.dataset.nk]=true;log('emp',u.id,'Уведомления: «'+NKINDS.find(k=>k[0]===x.dataset.nk)[1]+'» '+(x.checked?'включено':'отключено'));toast(x.checked?'Включено':'Отключено','bell')})}
// Реквизит сотрудника (решение заказчика 25.10.2026): «Счёт или кошелёк» или «Перевод по номеру телефона»; w — изменить существующий
function walletDlg(u,done,w){const ed=!!w;const st={k:w?w.kind||'acc':'acc'};const ws=u.wallets||[];
  openModal({form:true,render:()=>({title:ed?'Изменить реквизит':'Новый реквизит',sub:'Куда контрагенты переводят деньги на налоги',body:`<div class="form">${fld('Вид',rqKindSel('w-k',st.k),{full:true,id:'w-k'})}
    <div class="fld full rq-g" data-rqg="acc" ${st.k==='acc'?'':'hidden'}><div class="form">${fld('Банковский провайдер',sel('w-prov',rqProvs(false,w&&w.prov?[w.prov]:[]),w&&w.prov||''),{req:true,id:'w-prov'})}${fld('Номер счёта или кошелька',inp('w-num',w&&w.num||'','class="inp mono" inputmode="numeric"'),{req:true,id:'w-num'})}</div></div>
    <div class="fld full rq-g" data-rqg="phone" ${st.k==='phone'?'':'hidden'}><div class="form">${fld('Номер телефона',phoneInput('w-ph',w&&w.phone||null),{req:true,id:'w-ph'})}${fld('Банки и кошельки, к которым привязан номер',rqBanksFld('w-bs',w&&w.banks||[]),{req:true,full:true,id:'w-bs',hint:'Отметьте все, где открыт этот номер: по номеру переводят внутри одного банка или кошелька'})}</div></div>
    ${fld('Имя получателя',inp('w-name',w?w.name||'':u.short||''),{id:'w-name',hint:'Необязательно; так, как его видит отправитель, например «Асанов А.»'})}<div class="fld"><label class="lbl">&nbsp;</label><label class="row"><input type="checkbox" id="w-main" ${w?w.main?'checked':'':ws.length?'':'checked'}> Основной</label></div></div>`,
    foot:`<button class="btn ghost" data-close>Отмена</button><button class="btn cta" id="w-ok">${ed?'Сохранить':'Добавить'}</button>`,
    mount(el,m){bindPhone(el,'w-ph');$('#w-k',el).onclick=e=>{const b=e.target.closest('[data-rqk]');if(!b)return;st.k=b.dataset.rqk;$$('[data-rqk]',el).forEach(x=>{x.classList.toggle('on',x===b);x.setAttribute('aria-pressed',x===b)});$$('[data-rqg]',el).forEach(g=>g.hidden=g.dataset.rqg!==st.k)};
      $('#w-ok',el).onclick=()=>{const x=w||{};if(st.k==='acc'){const n=val(el,'w-num');if(!setErr(el,'w-num',n.replace(/\D/g,'').length>=6?'':'Введите номер: не меньше 6 цифр'))return;Object.assign(x,{kind:'acc',prov:val(el,'w-prov'),num:n});delete x.phone;delete x.banks}
        else{const p=readPhone(el,'w-ph'),bs=rqBanksRead(el,'w-bs');if(![setErr(el,'w-ph',p.ok?'':`Введите номер полностью: ${p.need} цифр после кода страны`),setErr(el,'w-bs',bs.length?'':'Отметьте хотя бы один банк или кошелёк')].every(Boolean))return;Object.assign(x,{kind:'phone',phone:p.ph,banks:bs});delete x.prov;delete x.num}
        u.wallets=u.wallets||[];const main=$('#w-main',el).checked;if(main)u.wallets.forEach(y=>y.main=false);x.name=val(el,'w-name');x.main=main;if(!w)u.wallets.push(x);if(!u.wallets.some(y=>y.main))u.wallets[0].main=true;
        log('emp',u.id,`${ed?'Изменён':'Добавлен'} реквизит для переводов: ${rqTxt(x)}`);m.close();toast(ed?'Реквизит изменён':'Реквизит добавлен');done&&done()}}})});
}
function orgProfileDlg(){
  openModal({size:'mid',render:()=>({title:esc(ORG.name),sub:'Профиль организации · только просмотр',body:orgMainView(),foot:`${can('org')?`<button class="btn" id="op-edit">${ic('edit','sm')}Редактировать</button>`:''}<button class="btn cta" data-close>Закрыть</button>`,mount(el,m){const b=$('#op-edit',el);if(b)b.onclick=()=>{m.close();go('org','main')}}})});
}
function orgMainView(){return `<div class="box"><h3>Основное</h3><div class="kv"><div><span class="k">Название</span><span class="v">${esc(ORG.name)}</span></div><div><span class="k">ИНН</span><span class="v mono">${ORG.inn}</span></div><div><span class="k">Адрес</span><span class="v">${esc(ORG.address)}</span></div><div><span class="k">Телефон</span><span class="v">${esc(fmtPhone(ORG.phone))}</span></div><div><span class="k">Руководитель</span><span class="v">${esc(ORG.head)}</span></div>${feat('cppage')?`<div><span class="k">Адрес страницы организации</span><span class="v mono">${esc(ORG.slug||'—')}</span></div>`:''}${ORG.logo?`<div><span class="k">Логотип</span><span class="v"><img src="${ORG.logo}" alt="Логотип" style="width:40px;height:40px;object-fit:contain"></span></div>`:''}<div><span class="k">На платформе с</span><span class="v">${fmtD(ORG.created)}</span></div></div></div>
  <div class="box"><h3>Реквизиты для приёма денег от контрагентов</h3><div class="tbl-wrap"><table class="mini m-cards">${orgAccHead()}<tbody id="og-accs">${orgAccRows()}</tbody></table></div></div>`}
// Замена Telegram (решение заказчика 07.11.2026): другой Telegram вместо прежнего — привязанного сейчас или отвязанного последним (u.tgPrev), «Отвязать» код не обходит — привязывается только кодом из 6 цифр, который бот присылает в прежний чат; новый чат присылает его боту, тот же чат ещё раз привязывается без кода. Пределы — как у «Забыли пароль?»: код действует 10 минут и 5 вводов, не больше 3 кодов в час, после 10 неверных за сутки замена закрыта на сутки. После сброса пароля владельцем или администратором платформы (u.tgFree) сутки другой Telegram привязывается один раз без кода
// В макете переписку с ботом в обоих чатах показывает окно предпросмотра; счётчики живут до перезагрузки страницы; бот всегда принимает сообщение, поэтому «Telegram: код замены не отправлен» здесь не бывает
const RL={},RL_TTL=10*60e3,RL_TRIES=5,RL_REQ=3,RL_BAD=10,RL_H=3600e3,RL_DAY=864e5,TG_RELINK='Код замены Telegram';
const rlSt=l=>{const st=RL[l]=RL[l]||{req:[],bad:[],code:null,at:0,tries:0,till:0},now=Date.now();st.req=st.req.filter(t=>now-t<RL_H);st.bad=st.bad.filter(t=>now-t<RL_DAY);if(st.till&&st.till<=now)st.till=0;return st};
const tplFill=(k,v)=>(TPL[k]||'').replace(/\{([^{}]+)\}/g,(m,x)=>v[x]??m);
const tgFreeOn=u=>!!u.tgFree&&Date.now()-u.tgFree<RL_DAY;
function tgRelinkDlg(u,done){const old=u.tg||u.tgPrev,nw='@'+u.login+'_2',name=nw.replace(/\s+/g,' ').slice(0,32),A=[],B=[];
  // Верный код: новый чат привязан; в прежний — «Telegram: привязан другой Telegram», в новый — «Telegram: привязан»
  const linkNew=()=>{A.push(tgSecSend(u,'relink',{chat:old,tg:nw}));u.tg=nw;delete u.tgPrev;log('emp',u.id,'Telegram привязан');tgSvc(u,'Telegram привязан');B.push({t:tplFill('tgLinked',{логин:u.login})});done&&done()};
  const st=rlSt(u.login);
  if(tgFreeOn(u)){delete u.tgFree;B.push({t:'/start',me:true});linkNew()}
  else if(st.till||st.req.length>=RL_REQ){B.push({t:'/start',me:true},{t:tplFill('tgRelinkLimited',{})})}
  else{st.req.push(Date.now());st.code=pgNewCode();st.at=Date.now();st.tries=0;tgSvc(u,TG_RELINK,{chat:old});
    A.push(tgCodeMsg('tgRelinkCode',{логин:u.login,телеграм:name,код:st.code,минут:10}));B.push({t:'/start',me:true},{t:tplFill('tgRelinkAsk',{логин:u.login,минут:10})})}
  // Оба чата — в общем виде чата бота (tg-chat.js): код в прежнем чате копируется нажатием и кнопкой «Скопировать код»
  const CA={who:'Прежний чат '+old,list:A},CB={who:'Новый чат '+nw,list:B};
  openModal({size:'mid',live:true,onClose:tgSecLeave,render:m=>({title:'Прототип: замена Telegram',sub:`Ссылку из «Мой профиль» открыли в другом Telegram — ${esc(nw)}`,
    body:`<div class="tgc-wrap two"><div id="rl-a">${tgcHtml(CA)}</div><div id="rl-b">${tgcHtml(CB)}</div></div>${u.tg===nw?'':`<div class="row" style="flex-wrap:wrap">${inp('rl-k','','inputmode="numeric" maxlength="6" class="inp mono" placeholder="Код из прежнего чата" style="max-width:220px"')}<button class="btn cta" id="rl-go">${ic('send','sm')}Отправить боту из нового чата</button></div>`}<div class="note">${ic('info')}<span>Так бот переписывается с прежним и новым чатом. Сообщение с кодом записано в журнал «Телеграм» с типом «Код замены Telegram», без текста кода. Тексты — Справочники платформы → Шаблоны.</span></div>`,
    foot:'<button class="btn cta" data-close>Готово</button>',
    mount(el){tgcBind($('#rl-a',el),CA,()=>m.draw(),u);const g=$('#rl-go',el);if(!g)return;const k0=$('#rl-k',el);
      const go=()=>{const k=k0.value.trim();if(!k)return;B.push({t:k,me:true});const s=rlSt(u.login),now=Date.now();
        if(s.till)B.push({t:tplFill('tgRelinkLimited',{})});
        else if(!s.code||now-s.at>RL_TTL||s.tries>=RL_TRIES)B.push({t:tplFill('tgRelinkFailed',{})});
        else{s.tries++;if(k===s.code){s.code=null;linkNew();toast('Telegram привязан','tg')}
          else{s.bad.push(now);if(s.bad.length>=RL_BAD){s.till=now+RL_DAY;s.code=null;B.push({t:tplFill('tgRelinkLimited',{})})}else if(s.tries>=RL_TRIES){s.code=null;B.push({t:tplFill('tgRelinkFailed',{})})}else B.push({t:tplFill('tgRelinkWrong',{попыток:Math.min(RL_TRIES-s.tries,RL_BAD-s.bad.length)})})}}
        m.draw()};
      g.onclick=go;k0.onkeydown=e=>{if(e.key==='Enter')go()};k0.focus()}})})}
